using System.Net;
using Microsoft.Azure.Functions.Worker;
using Microsoft.Azure.Functions.Worker.Http;
using Microsoft.Extensions.Logging;

public class HealthFunctions
{
    private readonly ILogger<HealthFunctions> _logger;

    public HealthFunctions(ILogger<HealthFunctions> logger)
    {
        _logger = logger;
    }

    [Function("Health")]
    public HttpResponseData Run(
        [HttpTrigger(AuthorizationLevel.Function, "get", Route = "health")]
        HttpRequestData request)
    {
        _logger.LogInformation("Health check requested at {Time}", DateTime.UtcNow);

        var response = request.CreateResponse(HttpStatusCode.OK);
        response.Headers.Add("Content-Type", "application/json");
        response.WriteString("{\"status\":\"healthy\"}");
        return response;
    }
}

[Function("Cleanup")]
public void Run(
    [TimerTrigger("0 0 2 * * *")] TimerInfo timer,
    FunctionContext context)
{
    var logger = context.GetLogger("Cleanup");
    logger.LogInformation("Cleanup started at {Time}", DateTime.UtcNow);

    // Delete expired records, close stale sessions, etc.
}
